const DEFAULT_STATE={favorites:[],notes:{},checklist:{},custom_checklist:[],profile:{adults:1,children:0,pets:0,days:3,water_liters:0,food_kcal:0,battery_wh:0},inventory:[],contacts:[],incident_log:[],risk_flags:[],communications:{},evacuation:{},medical_card:{},medications:[],waypoints:[],navigation:{},documents:[],maintenance:[],roles:[],drill_history:[],continuity:{},resource_plans:[],checkins:[],vehicles:[],kits:[],field_logs:[],routes:[],shelter_zones:[],water_batches:[],recovery_items:[],skill_matrix:[],decision_board:[],food_lots:[],sanitation_points:[],power_loads:[],comms_windows:[],dependents:[],expense_log:[],knowledge_progress:[],settings:{low_power:false},schema_version:7,updated_at:''};
let lang=localStorage.getItem('osp-lang')||'en',meta=null,state=structuredCloneSafe(DEFAULT_STATE),currentSection='dashboard',generatedTasks=[];
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const tx=k=>(T[lang]&&T[lang][k])||T.en[k]||k;
function structuredCloneSafe(v){return JSON.parse(JSON.stringify(v))}
function mergeState(raw){const out=structuredCloneSafe(DEFAULT_STATE);if(!raw||typeof raw!=='object')return out;for(const k of Object.keys(out)){if(raw[k]!==undefined)out[k]=raw[k]}out.profile={...DEFAULT_STATE.profile,...(raw.profile||{})};out.settings={...DEFAULT_STATE.settings,...(raw.settings||{})};return out}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function arg(v){return encodeURIComponent(String(v??'')).replace(/'/g,'%27')}
function toast(m){const e=$('#toast');e.textContent=m;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),1800)}
async function api(path,opt){const r=await fetch(path,opt);const d=await r.json().catch(()=>({error:r.statusText}));if(!r.ok)throw new Error(d.error||r.statusText);return d}
function fmt(n,d=0){return new Intl.NumberFormat(lang==='el'?'el-GR':'en-US',{maximumFractionDigits:d}).format(Number(n)||0)}
function nav(){const html=NAV.map(([id,ico])=>`<button data-go="${id}" class="${id===currentSection?'active':''}"><b>${ico}</b><span>${esc(tx(id))}</span></button>`).join('');$('#desktopNav').innerHTML=html;$('#mobileNav').innerHTML=MOBILE_NAV.map(id=>{const n=NAV.find(x=>x[0]===id);return `<button data-go="${id}" class="${id===currentSection?'active':''}"><b>${n[1]}</b>${esc(tx(id))}</button>`}).join('');$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));}
function applyLang(){document.documentElement.lang=lang;document.title=tx('appTitle');$$('[data-t]').forEach(e=>e.textContent=tx(e.dataset.t));$$('[data-ph]').forEach(e=>e.placeholder=tx(e.dataset.ph));nav();setTitle(currentSection);renderScenarios();hydrateForms();hydrateV3();renderChecklist();renderFavorites();renderRisks();renderInventory();renderContacts();renderMessages();renderIncidents();renderMedications();renderWaypoints();renderRoutes();renderDocuments();renderMaintenance();renderRoles();renderDrillHistory();renderDrillSelect();renderResourcePlans();renderKits();renderCheckins();renderFieldLogs();renderVehicles();renderReadiness();if(meta)renderMeta();}
function setTitle(id){$('#pageTitle').textContent=tx(id);const map={emergency:'emText',search:'searchHint',browse:'browseSub',essentials:'verifiedSub',food:'foodSub',operations:'toolsText',inventory:'inventoryText',communications:'contactsText',plan:'planText',health:'healthSub',navigation:'navigationSub',continuity:'continuitySub',training:'trainingSub',library:'libraryText',system:'privacyText'};$('#pageSub').textContent=id==='dashboard'?tx('dashboardSub'):tx(map[id]||'dashboardSub');}
function go(id){currentSection=id;$$('.section').forEach(s=>s.classList.toggle('active',s.id===id));nav();setTitle(id);window.scrollTo({top:0});if(id==='browse')loadCategories();if(id==='essentials')loadEssentials(true);if(id==='food')loadFood();if(id==='plan')renderFavorites();if(id==='library')refreshLibrary();if(id==='operations'){hydrateForms();renderReadiness();}if(id==='inventory')renderInventory();if(id==='communications'){renderContacts();renderMessages();renderIncidents();hydrateForms();}if(id==='health'){hydrateV3();renderMedications();}if(id==='navigation'){hydrateV3();renderWaypoints();}if(id==='continuity'){hydrateV3();renderDocuments();renderMaintenance();renderRoles();}if(id==='training'){renderDrillSelect();renderDrillHistory();generateTrainingPlan();}if(id==='resources'){renderResourcePlans();renderKits();}if(id==='accountability'){renderCheckins();renderFieldLogs();}if(id==='transport'){renderVehicles();}}
function renderScenarios(){const h=Object.entries(SC).map(([k,v])=>`<button class="scenario" onclick="scenario('${k}')"><span class="ico">${v[0]}</span><span>${esc(lang==='el'?v[2]:v[1])}</span></button>`).join('');$('#dashboardScenarios').innerHTML=h;$('#emergencyScenarios').innerHTML=h;}
async function scenario(k){go('emergency');$('#emergencyResults').innerHTML=`<div class="empty">${esc(tx('loading'))}</div>`;try{const d=await api(`/api/scenario?lang=${lang}&key=${encodeURIComponent(k)}`);$('#emResultsTitle').textContent=lang==='el'?SC[k][2]:SC[k][1];$('#emResultsSub').textContent=`${fmt(d.count)} ${tx('countResults')}`;renderResults('#emergencyResults',d.results)}catch(e){$('#emergencyResults').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function search(){const q=$('#searchInput').value.trim();if(!q)return;$('#searchResults').innerHTML=`<div class="empty">${esc(tx('loading'))}</div>`;try{const d=await api(`/api/search?lang=${lang}&q=${encodeURIComponent(q)}&limit=120`);$('#searchCount').textContent=`${fmt(d.count)} ${tx('countResults')}`;renderResults('#searchResults',d.results)}catch(e){$('#searchResults').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderResults(sel,rows){const root=$(sel);if(!rows||!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noResults'))}</div>`;return}root.innerHTML=rows.map(r=>`<article class="result" onclick="openRecord(decodeURIComponent('${arg(r.id)}'))"><h3>${esc(r.title||r.id)}</h3><p>${esc(r.summary||'')}</p><div class="meta"><span class="pill">${esc(r.category||'')}</span>${r.urgency?`<span class="pill">${esc(r.urgency)}</span>`:''}</div></article>`).join('')}
async function loadCategories(){if($('#categoryGrid').dataset.loaded===lang)return;try{const d=await api(`/api/categories?lang=${lang}`);$('#categoryGrid').dataset.loaded=lang;$('#categoryGrid').style.display='grid';$('#categoryResultHeader').style.display='none';$('#categoryResults').innerHTML='';$('#categoryGrid').innerHTML=d.categories.map(c=>`<button class="category" onclick="openCategory(decodeURIComponent('${arg(c.name)}'))"><strong>${esc(c.name)}</strong><span>${fmt(c.count)} ${tx('records')}</span></button>`).join('')}catch(e){$('#categoryGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function showCategories(){$('#categoryGrid').style.display='grid';$('#categoryResultHeader').style.display='none';$('#categoryResults').innerHTML=''}
