const FIELD={en:{category:'Category',subcategory:'Subcategory',summary:'Summary',content:'Full guidance',difficulty:'Difficulty',urgency:'Urgency',priority:'Priority',materials:'Materials',steps:'Steps',warnings:'Warnings',common_mistakes:'Common mistakes',alternatives:'Alternatives',failure_signs:'Failure signs',when_not_to_use:'When not to use',short_term:'Short-term actions',long_term:'Long-term actions',if_method_fails:'If the method fails',environment_notes:'Environment notes',related_topics:'Related topics',tags:'Tags',sources:'Sources',last_updated:'Last updated'},el:{category:'Κατηγορία',subcategory:'Υποκατηγορία',summary:'Σύνοψη',content:'Πλήρεις οδηγίες',difficulty:'Δυσκολία',urgency:'Επείγον',priority:'Προτεραιότητα',materials:'Υλικά',steps:'Βήματα',warnings:'Προειδοποιήσεις',common_mistakes:'Συνηθισμένα λάθη',alternatives:'Εναλλακτικές',failure_signs:'Ενδείξεις αποτυχίας',when_not_to_use:'Πότε να μη χρησιμοποιηθεί',short_term:'Βραχυπρόθεσμες ενέργειες',long_term:'Μακροπρόθεσμες ενέργειες',if_method_fails:'Αν η μέθοδος αποτύχει',environment_notes:'Σημειώσεις περιβάλλοντος',related_topics:'Σχετικά θέματα',tags:'Ετικέτες',sources:'Πηγές',last_updated:'Τελευταία ενημέρωση'}};
function valueHtml(v){if(Array.isArray(v))return `<ol>${v.map(x=>`<li>${esc(typeof x==='object'?JSON.stringify(x):x)}</li>`).join('')}</ol>`;if(v&&typeof v==='object')return `<div class="viewer">${esc(JSON.stringify(v,null,2))}</div>`;return `<p>${esc(v)}</p>`}
async function openRecord(id){try{showRecord(await api(`/api/record?lang=${lang}&id=${encodeURIComponent(id)}`))}catch(e){toast(e.message)}}
function showRecord(r){const id=String(r.id||'');$('#recordTitle').textContent=r.title||id;$('#recordMeta').textContent=[r.category].filter(Boolean).join(' · ');const order=['summary','content','urgency','priority','materials','steps','warnings','common_mistakes','alternatives','failure_signs','when_not_to_use','short_term','long_term','if_method_fails','environment_notes','related_topics','sources','last_updated'];const fav=state.favorites.includes(id);let h=`<div class="record-actions"><button class="btn ${fav?'primary':''}" id="favBtn" onclick="toggleFavorite(decodeURIComponent('${arg(id)}'))">${fav?'★ '+tx('unfavorite'):'☆ '+tx('favorite')}</button></div>`;for(const k of order){const v=r[k];if(v===undefined||v===null||v===''||(Array.isArray(v)&&!v.length))continue;h+=`<section class="record-section"><h4>${esc((FIELD[lang]||FIELD.en)[k]||k)}</h4>${valueHtml(v)}</section>`}h+=`<section class="record-section"><h4>${esc(tx('personalNote'))}</h4><textarea id="recordNote" class="note-box" placeholder="${esc(tx('personalNote'))}">${esc(state.notes[id]||'')}</textarea><div style="margin-top:8px"><button class="btn primary" onclick="saveRecordNote(decodeURIComponent('${arg(id)}'))">${esc(tx('saveNote'))}</button></div></section>`;$('#recordBody').innerHTML=h;openModal('recordModal')}
function toggleFavorite(id){const i=state.favorites.indexOf(id);if(i>=0)state.favorites.splice(i,1);else state.favorites.unshift(id);saveState();const b=$('#favBtn');if(b){const fav=state.favorites.includes(id);b.classList.toggle('primary',fav);b.textContent=fav?'★ '+tx('unfavorite'):'☆ '+tx('favorite')}renderFavorites()}
function saveRecordNote(id){const v=$('#recordNote').value.trim();if(v)state.notes[id]=v;else delete state.notes[id];saveState();toast(tx('copied'))}
async function saveState(){try{state=mergeState(await api('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)}));renderReadiness()}catch(e){toast(e.message)}}
function renderChecklist(){const root=$('#checklist');if(!root)return;root.innerHTML=CHECK[lang].map(([id,text])=>`<label class="check ${state.checklist[id]?'done':''}"><input type="checkbox" ${state.checklist[id]?'checked':''} onchange="setCheck('${id}',this.checked)"><span>${esc(text)}</span></label>`).join('');const c=$('#customChecklist');if(c)c.innerHTML=(state.custom_checklist||[]).map((x,i)=>`<label class="check ${x.done?'done':''}"><input type="checkbox" ${x.done?'checked':''} onchange="setCustom(${i},this.checked)"><span style="flex:1">${esc(x.text)}</span><button class="btn danger small" onclick="event.preventDefault();removeCustom(${i})">×</button></label>`).join('')||`<div class="empty">—</div>`}
function setCheck(id,v){state.checklist[id]=v;saveState();renderChecklist()}function setCustom(i,v){state.custom_checklist[i].done=v;saveState();renderChecklist()}function removeCustom(i){state.custom_checklist.splice(i,1);saveState();renderChecklist()}function addCustom(){const e=$('#customInput'),text=e.value.trim();if(!text)return;state.custom_checklist.push({id:'custom-'+Date.now(),text,done:false});e.value='';saveState();renderChecklist()}
async function renderFavorites(){const root=$('#favoriteResults');if(!root)return;if(!state.favorites.length){root.innerHTML=`<div class="empty">${esc(tx('noFavorites'))}</div>`;return}const rows=[];for(const id of state.favorites.slice(0,80)){try{const r=await api(`/api/record?lang=${lang}&id=${encodeURIComponent(id)}`);rows.push({id:r.id,title:r.title,category:r.category,summary:r.summary})}catch{}}renderResults('#favoriteResults',rows)}
let libraryCache=[];async function refreshLibrary(){const g=$('#libraryGrid');g.innerHTML=`<div class="empty">${esc(tx('loading'))}</div>`;try{const d=await api('/api/library');g.dataset.root=d.root;libraryCache=d.files||[];renderLibraryFiles()}catch(e){g.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderLibraryFiles(){const g=$('#libraryGrid');if(!g)return;const q=($('#libraryFilter')?.value||'').toLowerCase(),kind=$('#libraryKind')?.value||'',rows=libraryCache.filter(f=>(!kind||f.kind===kind)&&(!q||[f.name,f.path,f.kind].join(' ').toLowerCase().includes(q)));if($('#libraryCount'))$('#libraryCount').textContent=`${fmt(rows.length)} / ${fmt(libraryCache.length)}`;g.innerHTML=rows.length?rows.map(f=>`<div class="card library-item"><h3>${esc(f.name)}</h3><div class="meta"><span class="pill">${esc(f.kind)}</span><span class="pill">${esc(f.size_human)}</span></div><code>${esc(f.path)}</code><div class="row">${f.readable?`<button class="btn" onclick="readLibrary(decodeURIComponent('${arg(f.path)}'))">${esc(tx('read'))}</button>`:''}${f.kiwix?`<button class="btn primary" onclick="openKiwix(decodeURIComponent('${arg(f.path)}'))">${esc(tx('openKiwix'))}</button>`:`<a class="btn" style="text-decoration:none" href="/library/${encodeURI(f.path)}" target="_blank" rel="noopener noreferrer">${esc(tx('details'))}</a>`}<button class="btn" onclick="hashLibrary(decodeURIComponent('${arg(f.path)}'))">${esc(tx('hashFile'))}</button></div></div>`).join(''):`<div class="empty">${esc(tx('noLibrary'))}</div>`}
async function readLibrary(path){try{const d=await api(`/api/library/text?path=${encodeURIComponent(path)}`);$('#viewerTitle').textContent=path;$('#viewerBody').innerHTML=`<div class="viewer">${esc(d.text)}</div>`;openModal('viewerModal')}catch(e){toast(e.message)}}
async function searchLibraryContents(){const root=$('#libraryContentResults'),q=$('#libraryContentQuery').value.trim();if(q.length<2){root.innerHTML=`<div class="empty">${esc(tx('librarySearchNeedQuery'))}</div>`;return}root.innerHTML=`<div class="empty">${esc(tx('loading'))}</div>`;try{const d=await api(`/api/library/search?q=${encodeURIComponent(q)}&limit=60`);root.innerHTML=d.results?.length?`<div class="results">${d.results.map(x=>`<div class="result"><div class="toolbar"><div class="grow"><h3>${esc(x.name)}</h3><div class="meta"><span class="pill">${esc(x.kind)}</span><span class="pill">${esc(x.size_human)}</span></div></div><button class="btn" onclick="readLibrary(decodeURIComponent('${arg(x.path)}'))">${esc(tx('read'))}</button></div><p>${esc(x.snippet||'')}</p><code>${esc(x.path)}</code></div>`).join('')}</div>`:`<div class="empty">${esc(tx('noLibrarySearchResults'))}</div>`}catch(e){root.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function openKiwix(path){try{const d=await api('/api/kiwix/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});if(d.ok)window.open(d.url,'_blank');else{$('#viewerTitle').textContent='Kiwix';$('#viewerBody').innerHTML=`<p>${esc(d.error||tx('libraryHelp'))}</p><p><strong>${esc(tx('filePath'))}:</strong><br><code>${esc(path)}</code></p>`;openModal('viewerModal')}}catch(e){toast(e.message)}}
function showLibraryPath(){const p=$('#libraryGrid').dataset.root||'Offline Library';$('#viewerTitle').textContent=tx('filePath');$('#viewerBody').innerHTML=`<div class="viewer">${esc(p)}</div>`;openModal('viewerModal')}
function renderMeta(){if(!meta)return;const r=meta.report.languages[lang]||{},sys=meta.system;$('#statRecords').textContent=fmt(r.records);$('#statCategories').textContent=fmt(r.category_folders);$('#statEssentials').textContent=fmt(meta.verified_essentials);$('#statFree').textContent=sys.disk_free_human;$('#systemList').innerHTML=[[tx('platform'),sys.platform],['Python',sys.python],[tx('projectSize'),sys.project_size_human],[tx('offlineLibraryLabel'),`${sys.library_files} · ${sys.library_size_human}`],[tx('kiwixServer'),sys.kiwix_available?tx('available'):tx('notInstalledShort')],[tx('diskFree'),sys.disk_free_human]].map(x=>`<div class="system-item"><small>${esc(x[0])}</small><strong>${esc(x[1])}</strong></div>`).join('');const ok=meta.report.ok;$('#integrityPanel').innerHTML=`<p style="color:${ok?'var(--accent)':'var(--danger)'};font-weight:800">${esc(ok?tx('allPassed'):tx('checkIssues'))}</p><p>EN: ${fmt(meta.report.languages.en.records)} · GR: ${fmt(meta.report.languages.el.records)}</p><p>${esc(tx('paths'))}: ${meta.report.paths_match?'✓':'✕'} · ${esc(tx('ids'))}: ${meta.report.ids_match?'✓':'✕'} · ${esc(tx('fileIds'))}: ${meta.report.file_ids_match?'✓':'✕'}</p>`}
function hydrateForms(){const p=state.profile||DEFAULT_STATE.profile;const ids={pAdults:p.adults,pChildren:p.children,pPets:p.pets,pDays:p.days,pWater:p.water_liters,pFood:p.food_kcal,pBattery:p.battery_wh,waterPeople:Math.max(1,(+p.adults||0)+(+p.children||0)),waterDays:p.days,powerDays:p.days};for(const [id,val] of Object.entries(ids)){const e=$('#'+id);if(e&&document.activeElement!==e)e.value=val}const c=state.communications||{};for(const [id,key] of [['commPrimary','primary'],['commBackup','backup'],['commSchedule','schedule'],['commOutside','outside']]){const e=$('#'+id);if(e)e.value=c[key]||''}const ev=state.evacuation||{};for(const [id,key] of [['evacMeeting','meeting'],['evacAlternate','alternate'],['evacRoute','route'],['evacAltRoute','alt_route'],['evacGrab','grab'],['evacNotes','notes']]){const e=$('#'+id);if(e)e.value=ev[key]||''}document.documentElement.classList.toggle('low-power',!!state.settings?.low_power)}
function saveProfile(){state.profile={adults:+$('#pAdults').value||0,children:+$('#pChildren').value||0,pets:+$('#pPets').value||0,days:Math.max(1,+$('#pDays').value||3),water_liters:+$('#pWater').value||0,food_kcal:+$('#pFood').value||0,battery_wh:+$('#pBattery').value||0};saveState();hydrateForms();renderReadiness();toast(tx('copied'))}
function calcWater(){const people=Math.max(1,+$('#waterPeople').value||1),days=Math.max(1,+$('#waterDays').value||1),rate=Math.max(.1,+$('#waterRate').value||0),reserve=Math.max(0,+$('#waterReserve').value||0);const base=people*days*rate,total=base*(1+reserve/100),stock=+state.profile.water_liters||0,coverage=rate>0?stock/(people*rate):0;$('#waterResult').innerHTML=`<strong>${fmt(total,1)} L</strong><small>${tx('roughEstimate')} ${tx('currentStock')}: ${fmt(stock,1)} L · ${tx('coverage')}: ${fmt(coverage,1)} ${tx('days').toLowerCase()}</small>`}
function calcPower(){const w=Math.max(0,+$('#powerWatts').value||0),h=Math.min(24,Math.max(0,+$('#powerHours').value||0)),d=Math.max(1,+$('#powerDays').value||1),eff=Math.min(100,Math.max(1,+$('#powerEff').value||85))/100,wh=w*h*d/eff,stock=+state.profile.battery_wh||0;$('#powerResult').innerHTML=`<strong>${fmt(wh,0)} Wh</strong><small>${tx('requiredEnergy')} · ${tx('currentStock')}: ${fmt(stock,0)} Wh</small>`}
function calcNav(){const a=[+$('#latA').value,+$('#lonA').value],b=[+$('#latB').value,+$('#lonB').value];if(!a.concat(b).every(Number.isFinite)||Math.abs(a[0])>90||Math.abs(b[0])>90||Math.abs(a[1])>180||Math.abs(b[1])>180){$('#navResult').textContent='Invalid coordinates';return}const R=6371,toR=x=>x*Math.PI/180,dlat=toR(b[0]-a[0]),dlon=toR(b[1]-a[1]),p1=toR(a[0]),p2=toR(b[0]);const aa=Math.sin(dlat/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dlon/2)**2,dist=2*R*Math.asin(Math.min(1,Math.sqrt(aa)));const y=Math.sin(dlon)*Math.cos(p2),x=Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(dlon),bearing=(Math.atan2(y,x)*180/Math.PI+360)%360;$('#navResult').innerHTML=`<strong>${fmt(dist,2)} km</strong><small>${tx('distance')} · ${tx('bearing')}: ${fmt(bearing,1)}°</small>`}
function calcUnit(){const v=+$('#unitValue').value,m=$('#unitMode').value;let out=0,label='';const f={ 'l-gal':[x=>x*0.264172,'US gal'],'gal-l':[x=>x/0.264172,'L'],'kg-lb':[x=>x*2.20462262,'lb'],'lb-kg':[x=>x/2.20462262,'kg'],'km-mi':[x=>x*0.621371,'mi'],'mi-km':[x=>x/0.621371,'km'],'c-f':[x=>x*9/5+32,'°F'],'f-c':[x=>(x-32)*5/9,'°C'],'wh-ah5':[x=>x/5,'Ah @ 5V'],'ah5-wh':[x=>x*5,'Wh']};[out,label]=[f[m][0](v),f[m][1]];$('#unitResult').innerHTML=`<strong>${fmt(out,3)} ${label}</strong>`}
function renderRisks(){const root=$('#riskGrid');if(!root)return;root.innerHTML=Object.entries(RISKS).map(([id,r])=>`<button class="risk-chip ${(state.risk_flags||[]).includes(id)?'active':''}" onclick="toggleRisk('${id}')">${r.ico} ${esc(r[lang]||r.en)}</button>`).join('')}
function toggleRisk(id){state.risk_flags=state.risk_flags||[];const i=state.risk_flags.indexOf(id);if(i>=0)state.risk_flags.splice(i,1);else state.risk_flags.push(id);saveState();renderRisks();renderReadiness()}
function generateRiskPlan(){const existing=new Set((state.custom_checklist||[]).map(x=>x.text));let n=0;for(const id of state.risk_flags||[]){for(const text of RISKS[id]?.tasks?.[lang]||[]){if(!existing.has(text)){state.custom_checklist.push({id:'risk-'+Date.now()+'-'+n,text,done:false});existing.add(text);n++}}}saveState();renderChecklist();toast(`${n} ${tx('generated').toLowerCase()}`)}
function renderReadiness(){const root=$('#readinessBreakdown');if(!root)return;const base=CHECK[lang].length,done=CHECK[lang].filter(([id])=>state.checklist[id]).length,check=base?done/base:0;const p=state.profile||{},profile=((+p.adults||0)+(+p.children||0)>0&&(+p.days||0)>0)?1:0;const inv=Math.min(1,(state.inventory||[]).length/8);const comm=Math.min(1,((state.contacts||[]).length?0.55:0)+(state.communications&&Object.keys(state.communications).length?0.45:0));const ev=state.evacuation||{},evac=(ev.meeting&&ev.route)?1:(ev.meeting||ev.route)?.5:0;const health=Math.min(1,((state.medical_card&&Object.values(state.medical_card).some(Boolean))?.55:0)+((state.medications||[]).length?.45:0));const navstate=state.navigation||{},navscore=Math.min(1,((navstate.origin_lat!==undefined&&navstate.origin_lon!==undefined)?.45:0)+((state.waypoints||[]).length?.55:0));const cont=Math.min(1,((state.documents||[]).length?.34:0)+((state.maintenance||[]).length?.33:0)+((state.roles||[]).length?.33:0));const parts=[[tx('readinessChecklist'),check,25],[tx('readinessProfile'),profile,10],[tx('readinessSupplies'),inv,15],[tx('readinessComms'),comm,10],[tx('readinessEvac'),evac,10],[tx('readinessHealth'),health,10],[tx('readinessNavigation'),navscore,10],[tx('readinessContinuity'),cont,10]];const score=Math.round(parts.reduce((a,[,v,w])=>a+v*w,0));$('#readinessScore').textContent=score+'%';$('#scoreRing').style.setProperty('--score',score+'%');root.innerHTML=parts.map(([name,v])=>`<div class="score-row"><span>${esc(name)}</span><div class="progress"><i style="width:${Math.round(v*100)}%"></i></div><b>${Math.round(v*100)}%</b></div>`).join('')}
function addInventory(){const name=$('#invName').value.trim();if(!name)return;state.inventory.push({id:'inv-'+Date.now(),name,category:$('#invCategory').value.trim(),qty:+$('#invQty').value||0,unit:$('#invUnit').value.trim(),expiry:$('#invExpiry').value,notes:''});$('#invName').value='';$('#invExpiry').value='';saveState();renderInventory()}
function inventoryStatus(expiry){if(!expiry)return 0;const t=new Date(expiry+'T12:00:00').getTime()-Date.now();const days=Math.ceil(t/86400000);return days<0?-1:days<=30?1:0}
function renderInventory(){const root=$('#inventoryTable');if(!root)return;const q=($('#invFilter')?.value||'').toLowerCase();const all=state.inventory||[],rows=all.filter(x=>[x.name,x.category,x.unit,x.expiry,x.notes].join(' ').toLowerCase().includes(q));$('#invCount').textContent=fmt(all.length);$('#invSoon').textContent=fmt(all.filter(x=>inventoryStatus(x.expiry)===1).length);$('#invExpired').textContent=fmt(all.filter(x=>inventoryStatus(x.expiry)===-1).length);$('#invGroups').textContent=fmt(new Set(all.map(x=>x.category).filter(Boolean)).size);if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noInventory'))}</div>`;return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('itemName')}</th><th>${tx('category')}</th><th>${tx('quantity')}</th><th>${tx('expiry')}</th><th></th></tr></thead><tbody>${rows.map(x=>{const st=inventoryStatus(x.expiry);return `<tr><td><strong>${esc(x.name)}</strong>${x.notes?`<br><small class="muted">${esc(x.notes)}</small>`:''}</td><td>${esc(x.category||'—')}</td><td>${fmt(x.qty,2)} ${esc(x.unit||'')}</td><td class="${st<0?'badge-danger':st>0?'badge-warn':''}">${esc(x.expiry||'—')}</td><td><button class="btn danger small" onclick="removeInventory(decodeURIComponent('${arg(x.id)}'))">${esc(tx('delete'))}</button></td></tr>`}).join('')}</tbody></table></div>`}
function removeInventory(id){state.inventory=state.inventory.filter(x=>x.id!==id);saveState();renderInventory()}
function csvCell(value){let s=String(value??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function csvRows(rows){return rows.map(r=>r.map(csvCell).join(',')).join('\n')}
function exportInventoryCSV(){const rows=[['name','category','quantity','unit','expiry','notes'],...(state.inventory||[]).map(x=>[x.name,x.category,x.qty,x.unit,x.expiry,x.notes])];downloadBlob(csvRows(rows),'offline-survival-inventory.csv','text/csv;charset=utf-8')}
function addContact(){const name=$('#contactName').value.trim();if(!name)return;state.contacts.push({id:'contact-'+Date.now(),name,role:$('#contactRole').value.trim(),phone:$('#contactPhone').value.trim(),meeting:$('#contactMeeting').value.trim(),notes:''});['contactName','contactRole','contactPhone','contactMeeting'].forEach(id=>$('#'+id).value='');saveState();renderContacts()}
function renderContacts(){const root=$('#contactsList');if(!root)return;root.innerHTML=(state.contacts||[]).length?(state.contacts||[]).map(x=>`<div class="result" style="cursor:default"><h3>${esc(x.name)}</h3><p>${esc([x.role,x.phone,x.meeting].filter(Boolean).join(' · '))}</p><div class="mini-actions"><button class="btn danger small" onclick="removeContact(decodeURIComponent('${arg(x.id)}'))">${esc(tx('delete'))}</button></div></div>`).join(''):`<div class="empty">${esc(tx('noContacts'))}</div>`}
function removeContact(id){state.contacts=state.contacts.filter(x=>x.id!==id);saveState();renderContacts()}
function saveCommunications(){state.communications={primary:$('#commPrimary').value.trim(),backup:$('#commBackup').value.trim(),schedule:$('#commSchedule').value.trim(),outside:$('#commOutside').value.trim()};saveState();toast(tx('copied'))}
function renderMessages(){const root=$('#messageTemplates');if(!root)return;root.innerHTML=MESSAGES[lang].map(([title,text])=>`<div class="message-card"><strong>${esc(title)}</strong><code>${esc(text)}</code><button class="btn small" style="margin-top:8px" onclick="copyText(decodeURIComponent('${arg(text)}'))">${esc(tx('copy'))}</button></div>`).join('')}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast(tx('copied'))}catch{$('#viewerTitle').textContent=tx('copy');$('#viewerBody').innerHTML=`<div class="viewer">${esc(text)}</div>`;openModal('viewerModal')}}
function addIncident(){const event=$('#logEvent').value.trim(),action=$('#logAction').value.trim();if(!event&&!action)return;state.incident_log.unshift({id:'log-'+Date.now(),time:new Date().toISOString(),event,action,status:$('#logStatus').value.trim()});['logEvent','logAction','logStatus'].forEach(id=>$('#'+id).value='');saveState();renderIncidents()}
function renderIncidents(){const root=$('#incidentTable');if(!root)return;const rows=state.incident_log||[];if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noIncidents'))}</div>`;return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${esc(tx('time'))}</th><th>${tx('event')}</th><th>${tx('action')}</th><th>${tx('status')}</th><th></th></tr></thead><tbody>${rows.slice(0,500).map(x=>`<tr><td>${esc(formatTime(x.time))}</td><td>${esc(x.event)}</td><td>${esc(x.action)}</td><td>${esc(x.status||'—')}</td><td><button class="btn danger small" onclick="removeIncident(decodeURIComponent('${arg(x.id)}'))">×</button></td></tr>`).join('')}</tbody></table></div>`}
function formatTime(v){try{return new Intl.DateTimeFormat(lang==='el'?'el-GR':'en-GB',{dateStyle:'short',timeStyle:'short'}).format(new Date(v))}catch{return v}}
function removeIncident(id){state.incident_log=state.incident_log.filter(x=>x.id!==id);saveState();renderIncidents()}
function generateActionPlan(){const p=state.profile||DEFAULT_STATE.profile,people=Math.max(1,(+p.adults||0)+(+p.children||0)),days=Math.max(1,+p.days||3);const t=lang==='el'?[`Επιβεβαίωσε σχέδιο για ${people} άτομα και ${days} ημέρες.`,`Έλεγξε νερό, τρόφιμα, φωτισμό, επικοινωνίες, φάρμακα και έγγραφα για τον επιλεγμένο ορίζοντα.`,`Κατέγραψε κύριο και εναλλακτικό σημείο συνάντησης.`,`Έλεγξε δύο τρόπους επικοινωνίας και πρόγραμμα check-in.`,`Κάνε οπτικό έλεγχο των εφοδίων για λήξεις, ζημιές και ελλείψεις.`]:[`Confirm the plan for ${people} people and ${days} days.`,`Review water, food, lighting, communications, medicines and documents for the selected horizon.`,`Record primary and alternate rendezvous points.`,`Verify two communication methods and a check-in schedule.`,`Visually inspect supplies for expiry, damage and gaps.`];for(const id of state.risk_flags||[])t.push(...(RISKS[id]?.tasks?.[lang]||[]));generatedTasks=[...new Set(t)];$('#generatedPlan').innerHTML=`<ol>${generatedTasks.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><button class="btn primary" onclick="addGeneratedPlan()">${esc(tx('addPlanTasks'))}</button>`}
function addGeneratedPlan(){const existing=new Set(state.custom_checklist.map(x=>x.text));let n=0;for(const text of generatedTasks){if(!existing.has(text)){state.custom_checklist.push({id:'plan-'+Date.now()+'-'+n++,text,done:false});existing.add(text)}}saveState();renderChecklist();toast(`${n} ${tx('generated').toLowerCase()}`)}
function saveEvacuation(){state.evacuation={meeting:$('#evacMeeting').value.trim(),alternate:$('#evacAlternate').value.trim(),route:$('#evacRoute').value.trim(),alt_route:$('#evacAltRoute').value.trim(),grab:$('#evacGrab').value.trim(),notes:$('#evacNotes').value.trim()};saveState();renderReadiness();toast(tx('copied'))}
function printEvacCard(){saveEvacuation();const e=state.evacuation;$('#viewerTitle').textContent=tx('evacTitle');$('#viewerBody').innerHTML=`<section class="record-section"><h4>${tx('meetingPoint')}</h4><p>${esc(e.meeting||'—')}</p></section><section class="record-section"><h4>${tx('alternateMeeting')}</h4><p>${esc(e.alternate||'—')}</p></section><section class="record-section"><h4>${tx('primaryRoute')}</h4><p>${esc(e.route||'—')}</p></section><section class="record-section"><h4>${tx('alternateRoute')}</h4><p>${esc(e.alt_route||'—')}</p></section><section class="record-section"><h4>${tx('grabList')}</h4><p>${esc(e.grab||'—')}</p></section><section class="record-section"><h4>${tx('notes')}</h4><p>${esc(e.notes||'—')}</p></section>`;openModal('viewerModal');setTimeout(()=>window.print(),100)}
function printSection(){window.print()}
function exportRedactedState(){const clean=structuredCloneSafe(DEFAULT_STATE);const payload={app:'Offline Survival Project',schema:7,redacted:true,exported_at:new Date().toISOString(),state:clean};downloadBlob(JSON.stringify(payload,null,2),'offline-survival-redacted-template.json','application/json')}
function printEmergencyBinder(){const p=state.profile||{},m=state.medical_card||{},ev=state.evacuation||{},c=state.communications||{};let h=`<section class="record-section"><h4>${esc(tx('household'))}</h4><p>${esc(`${p.adults||0} ${tx('adultsLabel')} · ${p.children||0} ${tx('childrenLabel')} · ${p.pets||0} ${tx('petsLabel')} · ${p.days||0} ${tx('planningDaysLabel')}`)}</p></section>`;h+=`<section class="record-section"><h4>${esc(tx('medicalCardTitle'))}</h4><p>${esc([m.person,m.blood,m.allergies,m.conditions,m.access].filter(Boolean).join(' · ')||'—')}</p></section>`;h+=`<section class="record-section"><h4>${esc(tx('contactsTitle'))}</h4><ul>${(state.contacts||[]).map(x=>`<li>${esc([x.name,x.role,x.phone,x.meeting].filter(Boolean).join(' · '))}</li>`).join('')||'<li>—</li>'}</ul></section>`;h+=`<section class="record-section"><h4>${esc(tx('commsPlanTitle'))}</h4><p>${esc([c.primary,c.backup,c.schedule,c.outside].filter(Boolean).join(' · ')||'—')}</p></section>`;h+=`<section class="record-section"><h4>${esc(tx('evacTitle'))}</h4><p>${esc([ev.meeting,ev.alternate,ev.route,ev.alt_route,ev.grab].filter(Boolean).join(' · ')||'—')}</p></section>`;h+=`<section class="record-section"><h4>${esc(tx('waypointTitle'))}</h4><ul>${(state.waypoints||[]).map(x=>`<li>${esc(x.name)} — ${(+x.lat).toFixed(5)}, ${(+x.lon).toFixed(5)}</li>`).join('')||'<li>—</li>'}</ul></section>`;h+=`<section class="record-section"><h4>${esc(tx('rolesTitle'))}</h4><ul>${(state.roles||[]).map(x=>`<li>${esc(x.name)} — ${esc(x.primary||'—')} / ${esc(x.backup||'—')}</li>`).join('')||'<li>—</li>'}</ul></section>`;$('#viewerTitle').textContent=tx('binderTitle');$('#viewerBody').innerHTML=h;openModal('viewerModal');setTimeout(()=>window.print(),100)}
function exportState(){const payload={app:'Offline Survival Project',schema:7,exported_at:new Date().toISOString(),state};downloadBlob(JSON.stringify(payload,null,2),'offline-survival-backup.json','application/json')}
function downloadBlob(text,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importState(file){if(!file)return;try{const raw=JSON.parse(await file.text()),candidate=raw.state||raw;if(!candidate||typeof candidate!=='object')throw new Error('bad');state=mergeState(candidate);await saveState();hydrateForms();applyLang();toast(tx('backupRestored'))}catch{toast(tx('invalidBackup'))}finally{$('#importStateFile').value=''}}
function toggleLowPower(){state.settings=state.settings||{};state.settings.low_power=!state.settings.low_power;document.documentElement.classList.toggle('low-power',state.settings.low_power);saveState()}
function openModal(id){$('#'+id).classList.add('open');document.body.style.overflow='hidden'}function closeModal(id){$('#'+id).classList.remove('open');document.body.style.overflow=''}function modalBackdrop(e,id){if(e.target.id===id)closeModal(id)}
