const DRILL_LABELS={earthquake:['Earthquake','Σεισμός'],wildfire:['Wildfire','Πυρκαγιά'],outage:['Power outage','Διακοπή ρεύματος'],flood:['Flood','Πλημμύρα'],communications:['Communications outage','Διακοπή επικοινωνιών'],evacuation:['Evacuation','Εκκένωση']};
let drillSession=null,drillTimer=null,compassHandler=null;
function hydrateV3(){
 const m=state.medical_card||{};for(const [id,key] of [['medPerson','person'],['medBlood','blood'],['medAllergies','allergies'],['medConditions','conditions'],['medAccess','access'],['medClinician','clinician'],['medEmergency','emergency'],['medNotes','notes']]){const e=$('#'+id);if(e)e.value=m[key]||''}
 const n=state.navigation||{};if($('#navOriginLat'))$('#navOriginLat').value=n.origin_lat??'';if($('#navOriginLon'))$('#navOriginLon').value=n.origin_lon??'';
}
function saveMedicalCard(){state.medical_card={person:$('#medPerson').value.trim(),blood:$('#medBlood').value.trim(),allergies:$('#medAllergies').value.trim(),conditions:$('#medConditions').value.trim(),access:$('#medAccess').value.trim(),clinician:$('#medClinician').value.trim(),emergency:$('#medEmergency').value.trim(),notes:$('#medNotes').value.trim()};saveState();toast(tx('save'))}
function printMedicalCard(){saveMedicalCard();const m=state.medical_card||{},rows=[[tx('personName'),m.person],[tx('bloodType'),m.blood],[tx('allergies'),m.allergies],[tx('conditions'),m.conditions],[tx('accessNeeds'),m.access],[tx('medicalContact'),m.clinician],[tx('medicalEmergencyContact'),m.emergency],[tx('medicalNotes'),m.notes]];$('#viewerTitle').textContent=tx('medicalCardTitle');$('#viewerBody').innerHTML=rows.map(([a,b])=>`<section class="record-section"><h4>${esc(a)}</h4><p>${esc(b||'—')}</p></section>`).join('');openModal('viewerModal');setTimeout(()=>window.print(),100)}
function addMedication(){const name=$('#rxName').value.trim();if(!name)return;state.medications.push({id:'med-'+Date.now(),name,purpose:$('#rxPurpose').value.trim(),instructions:$('#rxInstructions').value.trim(),on_hand:+$('#rxQty').value||0,unit:$('#rxUnit').value.trim(),refill:$('#rxRefill').value,notes:''});['rxName','rxPurpose','rxQty','rxUnit','rxRefill','rxInstructions'].forEach(id=>$('#'+id).value='');saveState();renderMedications()}
function reviewStatus(date){if(!date)return 0;const d=Math.ceil((new Date(date+'T12:00:00')-Date.now())/86400000);return d<0?-1:d<=30?1:0}
function renderMedications(){const root=$('#medicationsTable');if(!root)return;const rows=state.medications||[];$('#rxCount').textContent=fmt(rows.length);$('#rxSoon').textContent=fmt(rows.filter(x=>reviewStatus(x.refill)===1).length);$('#rxPast').textContent=fmt(rows.filter(x=>reviewStatus(x.refill)===-1).length);$('#rxInstructionsCount').textContent=fmt(rows.filter(x=>x.instructions).length);if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noMedications'))}</div>`;return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('medication')}</th><th>${tx('purpose')}</th><th>${tx('onHand')}</th><th>${tx('refillReview')}</th><th>${tx('labelInstructions')}</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.purpose||'—')}</td><td>${fmt(x.on_hand,2)} ${esc(x.unit||'')}</td><td class="${reviewStatus(x.refill)<0?'badge-danger':reviewStatus(x.refill)>0?'badge-warn':''}">${esc(x.refill||'—')}</td><td>${esc(x.instructions||'—')}</td><td><button class="btn danger small" onclick="removeMedication('${arg(x.id)}')">×</button></td></tr>`).join('')}</tbody></table></div>`}
function removeMedication(id){id=decodeURIComponent(id);state.medications=state.medications.filter(x=>x.id!==id);saveState();renderMedications()}
function saveOrigin(){const lat=+$('#navOriginLat').value,lon=+$('#navOriginLon').value;if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){toast(tx('invalidCoordinates'));return}state.navigation={...(state.navigation||{}),origin_lat:String(lat),origin_lon:String(lon)};saveState();renderWaypoints();$('#positionStatus').innerHTML=`<strong>${lat.toFixed(6)}, ${lon.toFixed(6)}</strong>`}
function capturePosition(){const box=$('#positionStatus');if(!navigator.geolocation){box.textContent=tx('positionUnavailable');return}box.textContent='…';navigator.geolocation.getCurrentPosition(p=>{$('#navOriginLat').value=p.coords.latitude.toFixed(7);$('#navOriginLon').value=p.coords.longitude.toFixed(7);saveOrigin();box.innerHTML=`<strong>${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)}</strong><small>± ${fmt(p.coords.accuracy,0)} m</small>`},()=>box.textContent=tx('positionUnavailable'),{enableHighAccuracy:true,timeout:12000,maximumAge:30000})}
function fillWaypointFromOrigin(){const n=state.navigation||{};if(n.origin_lat==null||n.origin_lon==null){toast(tx('originNeeded'));return}$('#wpLat').value=n.origin_lat;$('#wpLon').value=n.origin_lon}
function addWaypoint(){const name=$('#wpName').value.trim(),lat=+$('#wpLat').value,lon=+$('#wpLon').value;if(!name||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return;state.waypoints.push({id:'wp-'+Date.now(),name,type:$('#wpType').value.trim(),lat,lon,notes:$('#wpNotes').value.trim()});['wpName','wpType','wpLat','wpLon','wpNotes'].forEach(id=>$('#'+id).value='');saveState();renderWaypoints()}
function geoDistBearing(lat1,lon1,lat2,lon2){const R=6371,r=x=>x*Math.PI/180,p1=r(lat1),p2=r(lat2),dp=r(lat2-lat1),dl=r(lon2-lon1),a=Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2,d=2*R*Math.asin(Math.min(1,Math.sqrt(a))),y=Math.sin(dl)*Math.cos(p2),x=Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(dl),b=(Math.atan2(y,x)*180/Math.PI+360)%360;return [d,b]}
function renderWaypoints(){const root=$('#waypointsTable');if(!root)return;const rows=state.waypoints||[],n=state.navigation||{},has=n.origin_lat!==undefined&&n.origin_lon!==undefined,olat=+n.origin_lat,olon=+n.origin_lon;if(!rows.length)root.innerHTML=`<div class="empty">${esc(tx('noWaypoints'))}</div>`;else root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('name')}</th><th>${tx('type')}</th><th>${tx('coordinates')}</th><th>${tx('distanceFromOrigin')}</th><th></th></tr></thead><tbody>${rows.map(x=>{const db=has?geoDistBearing(olat,olon,+x.lat,+x.lon):null;return `<tr><td><strong>${esc(x.name)}</strong><br><small class="muted">${esc(x.notes||'')}</small></td><td>${esc(x.type||'—')}</td><td><code>${(+x.lat).toFixed(6)}, ${(+x.lon).toFixed(6)}</code></td><td>${db?`${fmt(db[0],2)} km · ${fmt(db[1],0)}°`:'—'}</td><td><button class="btn danger small" onclick="removeWaypoint('${arg(x.id)}')">×</button></td></tr>`}).join('')}</tbody></table></div>`;renderWaypointMap()}
function removeWaypoint(id){id=decodeURIComponent(id);state.waypoints=state.waypoints.filter(x=>x.id!==id);saveState();renderWaypoints()}
function renderWaypointMap(){const svg=$('#waypointMap');if(!svg)return;const rows=[...(state.waypoints||[])],n=state.navigation||{};if(n.origin_lat!==undefined&&n.origin_lon!==undefined)rows.unshift({name:'Origin',lat:+n.origin_lat,lon:+n.origin_lon,type:'origin'});let h='';for(let x=0;x<=700;x+=70)h+=`<line x1="${x}" y1="0" x2="${x}" y2="420" class="map-grid-line"/>`;for(let y=0;y<=420;y+=60)h+=`<line x1="0" y1="${y}" x2="700" y2="${y}" class="map-grid-line"/>`;if(!rows.length){svg.innerHTML=h;return}let minLat=Math.min(...rows.map(x=>+x.lat)),maxLat=Math.max(...rows.map(x=>+x.lat)),minLon=Math.min(...rows.map(x=>+x.lon)),maxLon=Math.max(...rows.map(x=>+x.lon));if(maxLat===minLat){maxLat+=.001;minLat-=.001}if(maxLon===minLon){maxLon+=.001;minLon-=.001}const xy=x=>[30+((+x.lon-minLon)/(maxLon-minLon))*640,390-((+x.lat-minLat)/(maxLat-minLat))*360],pts=rows.map(x=>xy(x));if(pts.length>1)h+=`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" class="map-route"/>`;rows.forEach((x,i)=>{const [px,py]=pts[i];h+=`<circle cx="${px}" cy="${py}" r="${x.type==='origin'?8:6}" class="map-point"/><text x="${Math.min(px+9,640)}" y="${Math.max(py-8,16)}" class="map-label">${esc(x.name)}</text>`});svg.innerHTML=h}
function exportWaypointsCSV(){const rows=[['name','type','latitude','longitude','notes'],...(state.waypoints||[]).map(x=>[x.name,x.type,x.lat,x.lon,x.notes])];downloadBlob(csvRows(rows),'offline-survival-waypoints.csv','text/csv;charset=utf-8')}
async function startCompass(){let D=window.DeviceOrientationEvent;if(!D){toast(tx('compassUnavailable'));return}try{if(typeof D.requestPermission==='function'){const p=await D.requestPermission();if(p!=='granted')throw 0}}catch{toast(tx('compassUnavailable'));return}if(compassHandler)window.removeEventListener('deviceorientation',compassHandler,true);compassHandler=e=>{let h=e.webkitCompassHeading;if(!Number.isFinite(h)&&Number.isFinite(e.alpha))h=(360-e.alpha)%360;if(!Number.isFinite(h))return;$('#compassHeading').textContent=`${Math.round(h)}°`;$('#compassNeedle').style.transform=`rotate(${h}deg)`};window.addEventListener('deviceorientation',compassHandler,true)}
function calcRations(){const p=state.profile||DEFAULT_STATE.profile,people=Math.max(1,(+p.adults||0)+(+p.children||0)),days=Math.max(1,+p.days||3),rate=Math.max(1,+$('#rationRate').value||1),target=people*days*rate,stock=+p.food_kcal||0,gap=Math.max(0,target-stock);$('#rationResult').innerHTML=`<strong>${tx('target')}: ${fmt(target,0)} kcal</strong><small>${tx('currentStock')}: ${fmt(stock,0)} kcal · ${tx('gap')}: ${fmt(gap,0)} kcal</small>`}
function calcFuel(){const liters=Math.max(0,+$('#fuelLiters').value||0),burn=Math.max(0,+$('#fuelBurn').value||0),hours=Math.max(0,+$('#fuelHoursDay').value||0);if(!burn){$('#fuelResult').textContent='—';return}const runtime=liters/burn,days=hours?runtime/hours:0;$('#fuelResult').innerHTML=`<strong>${tx('runtime')}: ${fmt(runtime,1)} h</strong><small>${tx('daysOfRuntime')}: ${fmt(days,1)}</small>`}
function calcSanitation(){const p=state.profile||DEFAULT_STATE.profile,people=Math.max(1,(+p.adults||0)+(+p.children||0)),days=Math.max(1,+p.days||3),uses=Math.max(0,+$('#sanUses').value||0),bags=Math.max(0,+$('#sanBags').value||0);$('#sanResult').innerHTML=`<strong>${tx('estimatedUses')}: ${fmt(people*days*uses,0)}</strong><small>${tx('estimatedBags')}: ${fmt(days*bags,0)}</small>`}
function addDocument(){const name=$('#docName').value.trim();if(!name)return;state.documents.push({id:'doc-'+Date.now(),name,copy_type:$('#docType').value.trim(),location:$('#docLocation').value.trim(),review:$('#docReview').value,notes:$('#docNotes').value.trim()});['docName','docType','docLocation','docReview','docNotes'].forEach(id=>$('#'+id).value='');saveState();renderDocuments()}
function renderDocuments(){const root=$('#documentsTable');if(!root)return;const rows=state.documents||[];if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noDocuments'))}</div>`;return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('document')}</th><th>${tx('copyType')}</th><th>${tx('location')}</th><th>${tx('reviewDate')}</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br><small class="muted">${esc(x.notes||'')}</small></td><td>${esc(x.copy_type||'—')}</td><td>${esc(x.location||'—')}</td><td class="${reviewStatus(x.review)<0?'badge-danger':reviewStatus(x.review)>0?'badge-warn':''}">${esc(x.review||'—')}</td><td><button class="btn danger small" onclick="removeDocument('${arg(x.id)}')">×</button></td></tr>`).join('')}</tbody></table></div>`}
function removeDocument(id){id=decodeURIComponent(id);state.documents=state.documents.filter(x=>x.id!==id);saveState();renderDocuments()}
function addMaintenance(){const task=$('#maintTask').value.trim();if(!task)return;state.maintenance.push({id:'maint-'+Date.now(),task,interval_days:Math.max(1,+$('#maintInterval').value||30),last_done:$('#maintLast').value,notes:$('#maintNotes').value.trim()});['maintTask','maintLast','maintNotes'].forEach(id=>$('#'+id).value='');saveState();renderMaintenance()}
function maintDue(x){if(!x.last_done)return null;const next=new Date(x.last_done+'T12:00:00').getTime()+(+x.interval_days||30)*86400000;return {date:new Date(next),days:Math.ceil((next-Date.now())/86400000)}}
function renderMaintenance(){const root=$('#maintenanceTable');if(!root)return;const rows=state.maintenance||[];if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noMaintenance'))}</div>`;return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('task')}</th><th>${tx('intervalDays')}</th><th>${tx('lastDone')}</th><th>${tx('due')}</th><th></th></tr></thead><tbody>${rows.map(x=>{const d=maintDue(x),cls=d&&d.days<0?'badge-danger':d&&d.days<=7?'badge-warn':'';return `<tr><td><strong>${esc(x.task)}</strong><br><small class="muted">${esc(x.notes||'')}</small></td><td>${fmt(x.interval_days)}</td><td>${esc(x.last_done||'—')}</td><td class="${cls}">${d?esc(d.date.toISOString().slice(0,10)):'—'}</td><td><div class="mini-actions"><button class="btn small" onclick="completeMaintenance('${arg(x.id)}')">${tx('markDone')}</button><button class="btn danger small" onclick="removeMaintenance('${arg(x.id)}')">×</button></div></td></tr>`}).join('')}</tbody></table></div>`}
function completeMaintenance(id){id=decodeURIComponent(id);const x=state.maintenance.find(x=>x.id===id);if(x)x.last_done=new Date().toISOString().slice(0,10);saveState();renderMaintenance()}
function removeMaintenance(id){id=decodeURIComponent(id);state.maintenance=state.maintenance.filter(x=>x.id!==id);saveState();renderMaintenance()}
function addRole(){const name=$('#roleName').value.trim();if(!name)return;state.roles.push({id:'role-'+Date.now(),name,primary:$('#rolePrimary').value.trim(),backup:$('#roleBackup').value.trim(),skills:$('#roleSkills').value.trim()});['roleName','rolePrimary','roleBackup','roleSkills'].forEach(id=>$('#'+id).value='');saveState();renderRoles()}
function renderRoles(){const root=$('#rolesGrid');if(!root)return;const rows=state.roles||[];root.innerHTML=rows.length?rows.map(x=>`<div class="role-card"><strong>${esc(x.name)}</strong><p><b>${tx('primaryRole')}:</b> ${esc(x.primary||'—')}<br><b>${tx('backupRole')}:</b> ${esc(x.backup||'—')}</p><p class="muted">${esc(x.skills||'')}</p><button class="btn danger small" onclick="removeRole('${arg(x.id)}')">×</button></div>`).join(''):`<div class="empty">${esc(tx('noRoles'))}</div>`}
function removeRole(id){id=decodeURIComponent(id);state.roles=state.roles.filter(x=>x.id!==id);saveState();renderRoles()}
function renderDrillSelect(){const e=$('#drillScenario');if(!e)return;const cur=e.value;e.innerHTML=Object.keys(DRILLS).map(k=>`<option value="${k}">${esc((DRILL_LABELS[k]?(lang==='el'?DRILL_LABELS[k][1]:DRILL_LABELS[k][0]):k))}</option>`).join('');if(cur&&DRILLS[cur])e.value=cur;renderDrillInjects()}
function renderDrillInjects(){const root=$('#drillInjects');if(!root)return;const key=drillSession?.scenario||$('#drillScenario')?.value||'earthquake',arr=DRILLS[key]?.[lang]||[],revealed=drillSession?.revealed||0;root.innerHTML=arr.map((x,i)=>`<div class="inject ${i<revealed?'':'locked'}"><strong>${i+1}</strong>${i<revealed?esc(x):'••••••••'}</div>`).join('')}
function startDrill(){const scenario=$('#drillScenario').value;drillSession={scenario,start:Date.now(),revealed:1};$('#drillNotes').value='';clearInterval(drillTimer);drillTimer=setInterval(updateDrillClock,1000);updateDrillClock();renderDrillInjects();$('#drillStatus').textContent=tx('startDrill')}
function updateDrillClock(){if(!drillSession){$('#drillClock').textContent='00:00';return}const sec=Math.floor((Date.now()-drillSession.start)/1000),m=String(Math.floor(sec/60)).padStart(2,'0'),s=String(sec%60).padStart(2,'0');$('#drillClock').textContent=`${m}:${s}`}
function revealNextInject(){if(!drillSession){startDrill();return}const total=DRILLS[drillSession.scenario][lang].length;drillSession.revealed=Math.min(total,drillSession.revealed+1);renderDrillInjects()}
function finishDrill(){if(!drillSession)return;clearInterval(drillTimer);const total=DRILLS[drillSession.scenario][lang].length,completed=drillSession.revealed,notes=$('#drillNotes').value.trim(),score=Math.round((completed/total)*70+(notes?30:0));state.drill_history.unshift({id:'drill-'+Date.now(),scenario:drillSession.scenario,time:new Date().toISOString(),completed,total,score,debrief:notes});drillSession=null;saveState();renderDrillHistory();renderDrillInjects();updateDrillClock();$('#drillStatus').textContent=tx('completed')}
function renderDrillHistory(){const root=$('#drillHistory');if(!root)return;const rows=state.drill_history||[];if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noDrills'))}</div>`;return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('scenario')}</th><th>${tx('time')}</th><th>${tx('completed')}</th><th>${tx('score')}*</th><th>${tx('debrief')}</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc((DRILL_LABELS[x.scenario]?(lang==='el'?DRILL_LABELS[x.scenario][1]:DRILL_LABELS[x.scenario][0]):x.scenario))}</td><td>${esc(formatTime(x.time))}</td><td>${fmt(x.completed)}/${fmt(x.total)}</td><td>${fmt(x.score)}%</td><td>${esc(x.debrief||'—')}</td><td><button class="btn danger small" onclick="removeDrill('${arg(x.id)}')">×</button></td></tr>`).join('')}</tbody></table><div class="doc-note">* ${esc(tx('interfaceScoreNote'))}</div></div>`}
function removeDrill(id){id=decodeURIComponent(id);state.drill_history=state.drill_history.filter(x=>x.id!==id);saveState();renderDrillHistory()}
function generateTrainingPlan(){const root=$('#trainingPlan');if(!root)return;const map={wildfire:'wildfire',flood:'flood',earthquake:'earthquake',power:'outage',communications:'communications',evacuation:'evacuation'},seq=[];for(const r of state.risk_flags||[]){const k=map[r];if(k&&!seq.includes(k))seq.push(k)};for(const k of ['outage','communications','evacuation'])if(!seq.includes(k))seq.push(k);root.innerHTML=`<ol>${seq.map((k,i)=>`<li><strong>${esc((DRILL_LABELS[k]?(lang==='el'?DRILL_LABELS[k][1]:DRILL_LABELS[k][0]):k))}</strong> — ${lang==='el'?`άσκηση ${i+1}`:`drill ${i+1}`}</li>`).join('')}</ol><p class="muted">${esc(tx('trainingGenerated'))}</p>`}

function simplifyRoutePoints(points,max=5000){if(points.length<=max)return points;const out=[];for(let i=0;i<max;i++)out.push(points[Math.round(i*(points.length-1)/(max-1))]);return out}
function extractGeoJSONPoints(obj){const candidates=[];const add=line=>{const pts=(line||[]).map(c=>Array.isArray(c)&&c.length>=2?[+c[1],+c[0]]:null).filter(p=>p&&Number.isFinite(p[0])&&Number.isFinite(p[1])&&Math.abs(p[0])<=90&&Math.abs(p[1])<=180);if(pts.length>=2)candidates.push(pts)};const visit=g=>{if(!g)return;if(g.type==='FeatureCollection'){(g.features||[]).forEach(visit);return}if(g.type==='Feature'){visit(g.geometry);return}if(g.type==='GeometryCollection'){(g.geometries||[]).forEach(visit);return}if(g.type==='LineString'){add(g.coordinates);return}if(g.type==='MultiLineString'){(g.coordinates||[]).forEach(add)}};visit(obj);candidates.sort((a,b)=>b.length-a.length);return candidates[0]||[]}
function extractGPXPoints(text){const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))return[];for(const selector of ['trkpt','rtept','wpt']){const pts=[...doc.querySelectorAll(selector)].map(n=>[+n.getAttribute('lat'),+n.getAttribute('lon')]).filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1])&&Math.abs(p[0])<=90&&Math.abs(p[1])<=180);if(pts.length>=2)return pts}return[]}
function routeDistance(points){let total=0;for(let i=1;i<points.length;i++)total+=geoDistBearing(points[i-1][0],points[i-1][1],points[i][0],points[i][1])[0];return total}
async function importRouteFile(){const input=$('#routeFile'),file=input?.files?.[0];if(!file)return;try{const text=await file.text(),lower=file.name.toLowerCase();let points=[];if(lower.endsWith('.gpx'))points=extractGPXPoints(text);else if(lower.endsWith('.geojson')||lower.endsWith('.json'))points=extractGeoJSONPoints(JSON.parse(text));points=simplifyRoutePoints(points);if(points.length<2){toast(tx('unsupportedRoute'));return}state.routes.unshift({id:'route-'+Date.now(),name:file.name.replace(/\.(gpx|geojson|json)$/i,''),source:lower.endsWith('.gpx')?'GPX':'GeoJSON',notes:'',points});state.routes=state.routes.slice(0,20);while(state.routes.reduce((n,r)=>n+(r.points?.length||0),0)>25000)state.routes.pop();input.value='';await saveState();renderRoutes();toast(tx('routeImported'))}catch(e){toast(e.message||tx('unsupportedRoute'))}}
function routeSvg(points){if(!points?.length)return'';let minLat=Math.min(...points.map(p=>p[0])),maxLat=Math.max(...points.map(p=>p[0])),minLon=Math.min(...points.map(p=>p[1])),maxLon=Math.max(...points.map(p=>p[1]));if(maxLat===minLat){maxLat+=.001;minLat-=.001}if(maxLon===minLon){maxLon+=.001;minLon-=.001}const xy=p=>[20+((p[1]-minLon)/(maxLon-minLon))*660,390-((p[0]-minLat)/(maxLat-minLat))*360],pts=points.map(xy);let h='';for(let x=0;x<=700;x+=70)h+=`<line x1="${x}" y1="0" x2="${x}" y2="420" class="map-grid-line"/>`;for(let y=0;y<=420;y+=60)h+=`<line x1="0" y1="${y}" x2="700" y2="${y}" class="map-grid-line"/>`;h+=`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" class="map-route"/><circle cx="${pts[0][0]}" cy="${pts[0][1]}" r="6" class="map-point"/><circle cx="${pts.at(-1)[0]}" cy="${pts.at(-1)[1]}" r="6" class="map-point"/>`;return h}
function renderRoutes(){const root=$('#routesGrid');if(!root)return;const rows=state.routes||[];root.innerHTML=rows.length?rows.map(r=>`<div class="card route-card"><div class="toolbar"><div class="grow"><h3>${esc(r.name)}</h3><div class="meta"><span class="pill">${esc(r.source||'')}</span><span class="pill">${fmt(r.points.length)} ${esc(tx('points').toLowerCase())}</span><span class="pill">${fmt(routeDistance(r.points),2)} km</span></div></div><button class="btn danger small" onclick="removeRoute('${arg(r.id)}')">×</button></div><svg class="route-map" viewBox="0 0 700 420" role="img" aria-label="${esc(r.name)}">${routeSvg(r.points)}</svg><div class="hash-line">${esc(r.points[0].map(x=>x.toFixed(5)).join(', '))} → ${esc(r.points.at(-1).map(x=>x.toFixed(5)).join(', '))}</div></div>`).join(''):`<div class="empty">${esc(tx('noRoutes'))}</div>`}
function removeRoute(id){id=decodeURIComponent(id);state.routes=(state.routes||[]).filter(x=>x.id!==id);saveState();renderRoutes()}
function exportRoutesGeoJSON(){const features=(state.routes||[]).map(r=>({type:'Feature',properties:{name:r.name,source:r.source||'',notes:r.notes||''},geometry:{type:'LineString',coordinates:r.points.map(p=>[p[1],p[0]])}}));downloadBlob(JSON.stringify({type:'FeatureCollection',features},null,2),'offline-survival-routes.geojson','application/geo+json')}

function addResourcePlan(){const name=$('#resName').value.trim();if(!name)return;state.resource_plans.push({id:'resource-'+Date.now(),name,stock:+$('#resStock').value||0,unit:$('#resUnit').value.trim(),daily_use:+$('#resDaily').value||0,reserve:+$('#resReserve').value||0,notes:''});['resName','resStock','resUnit','resDaily','resReserve'].forEach(id=>$('#'+id).value='');saveState();renderResourcePlans()}
function resourceDays(x){const usable=Math.max(0,(+x.stock||0)-(+x.reserve||0)),daily=Math.max(0,+x.daily_use||0);return daily?usable/daily:null}
function renderResourcePlans(){const root=$('#resourcePlans');if(!root)return;const rows=state.resource_plans||[];if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noResourcePlans'))}</div>`;return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('resource')}</th><th>${tx('stock')}</th><th>${tx('dailyUse')}</th><th>${tx('minimumReserve')}</th><th>${tx('daysRemaining')}</th><th></th></tr></thead><tbody>${rows.map(x=>{const d=resourceDays(x),pct=x.stock>0?Math.max(0,Math.min(100,((x.stock-x.reserve)/x.stock)*100)):0;return `<tr><td><strong>${esc(x.name)}</strong><div class="resource-bar"><span style="width:${pct}%"></span></div></td><td>${fmt(x.stock,2)} ${esc(x.unit||'')}</td><td>${fmt(x.daily_use,2)} ${esc(x.unit||'')}</td><td>${fmt(x.reserve,2)} ${esc(x.unit||'')}</td><td>${d==null?'—':fmt(d,1)}</td><td><button class="btn danger small" onclick="removeResourcePlan('${arg(x.id)}')">×</button></td></tr>`}).join('')}</tbody></table></div>`}
function removeResourcePlan(id){id=decodeURIComponent(id);state.resource_plans=(state.resource_plans||[]).filter(x=>x.id!==id);saveState();renderResourcePlans()}
function addKit(){const name=$('#kitName').value.trim();if(!name)return;state.kits.push({id:'kit-'+Date.now(),name,owner:$('#kitOwner').value.trim(),max_weight_kg:+$('#kitMax').value||0,notes:'',items:[]});['kitName','kitOwner','kitMax'].forEach(id=>$('#'+id).value='');saveState();renderKits()}
function addKitItem(id){id=decodeURIComponent(id);const kit=(state.kits||[]).find(x=>x.id===id);if(!kit)return;const name=document.getElementById(`ki-name-${id}`)?.value.trim();if(!name)return;kit.items.push({id:'kit-item-'+Date.now(),name,qty:+document.getElementById(`ki-qty-${id}`).value||1,weight_g:+document.getElementById(`ki-weight-${id}`).value||0,packed:false,critical:!!document.getElementById(`ki-critical-${id}`).checked,notes:''});saveState();renderKits()}
function toggleKitItem(kitId,itemId,packed){kitId=decodeURIComponent(kitId);itemId=decodeURIComponent(itemId);const kit=(state.kits||[]).find(x=>x.id===kitId),item=kit?.items?.find(x=>x.id===itemId);if(item)item.packed=!!packed;saveState();renderKits()}
function removeKitItem(kitId,itemId){kitId=decodeURIComponent(kitId);itemId=decodeURIComponent(itemId);const kit=(state.kits||[]).find(x=>x.id===kitId);if(kit)kit.items=kit.items.filter(x=>x.id!==itemId);saveState();renderKits()}
function removeKit(id){id=decodeURIComponent(id);state.kits=(state.kits||[]).filter(x=>x.id!==id);saveState();renderKits()}

function renderKits(){const root=$('#kitsGrid');if(!root)return;const rows=state.kits||[];if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noKits'))}</div>`;return}root.innerHTML=rows.map(k=>{const items=k.items||[],packed=items.filter(x=>x.packed).length,weight=items.reduce((a,x)=>a+(+x.qty||0)*(+x.weight_g||0),0)/1000,limit=+k.max_weight_kg||0,critical=items.filter(x=>x.critical&&!x.packed).length;return `<div class="card kit-card"><div class="toolbar"><div class="grow"><h3>${esc(k.name)}</h3><div class="meta"><span class="pill">${esc(k.owner||tx('none'))}</span><span class="pill">${tx('packProgress')}: ${packed}/${items.length}</span><span class="pill ${limit&&weight>limit?'badge-danger':''}">${fmt(weight,2)} kg${limit?` / ${fmt(limit,2)} kg`:''}</span>${critical?`<span class="pill badge-danger">${critical} ${esc(tx('missingCritical'))}</span>`:''}</div></div><button class="btn danger small" onclick="removeKit('${arg(k.id)}')">×</button></div><div class="kit-items">${items.map(x=>`<label class="kit-item ${x.critical&&!x.packed?'missing-critical':''}"><input type="checkbox" ${x.packed?'checked':''} onchange="toggleKitItem('${arg(k.id)}','${arg(x.id)}',this.checked)"><span><strong>${esc(x.name)}</strong><small class="muted">${fmt(x.qty,2)} × ${fmt(x.weight_g,0)} g ${x.critical?'· '+tx('critical'):''}</small></span><span>${fmt((+x.qty||0)*(+x.weight_g||0)/1000,2)} kg</span><button class="btn danger small" onclick="event.preventDefault();removeKitItem('${arg(k.id)}','${arg(x.id)}')">×</button></label>`).join('')}</div><div class="inline-form" style="margin-top:12px"><div class="field"><label>${tx('itemName')}</label><input id="ki-name-${esc(k.id)}"></div><div class="field"><label>${tx('quantity')}</label><input id="ki-qty-${esc(k.id)}" type="number" min="0" step="any" value="1"></div><div class="field"><label>${tx('weight')} (g)</label><input id="ki-weight-${esc(k.id)}" type="number" min="0" step="any"></div><label class="check"><input id="ki-critical-${esc(k.id)}" type="checkbox"><span>${tx('critical')}</span></label><button class="btn primary" onclick="addKitItem('${arg(k.id)}')">${tx('addItem')}</button></div></div>`}).join('')}

function addCheckin(){const name=$('#ciName').value.trim();if(!name)return;const entry={id:'checkin-'+Date.now(),name,status:$('#ciStatus').value,location:$('#ciLocation').value.trim(),time:new Date().toISOString(),next:$('#ciNext').value,notes:$('#ciNotes').value.trim()};state.checkins=(state.checkins||[]).filter(x=>x.name.toLocaleLowerCase()!==name.toLocaleLowerCase());state.checkins.unshift(entry);['ciName','ciLocation','ciNext','ciNotes'].forEach(id=>$('#'+id).value='');saveState();renderCheckins()}
function renderCheckins(){const root=$('#checkinBoard');if(!root)return;const rows=state.checkins||[];if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noCheckins'))}</div>`;return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('name')}</th><th>${tx('status')}</th><th>${tx('location')}</th><th>${tx('lastUpdate')}</th><th>${tx('nextCheckin')}</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br><small class="muted">${esc(x.notes||'')}</small></td><td><span class="status-chip ${esc(x.status||'unknown')}">${esc(tx(x.status==='ok'?'statusOk':x.status==='away'?'statusAway':x.status==='needs-help'?'statusNeedsHelp':'statusUnknown'))}</span></td><td>${esc(x.location||'—')}</td><td>${esc(formatTime(x.time))}</td><td>${esc(x.next?x.next.replace('T',' '):'—')}</td><td><button class="btn danger small" onclick="removeCheckin('${arg(x.id)}')">×</button></td></tr>`).join('')}</tbody></table></div>`}
function removeCheckin(id){id=decodeURIComponent(id);state.checkins=(state.checkins||[]).filter(x=>x.id!==id);saveState();renderCheckins()}
function addFieldLog(){const label=$('#fieldLabel').value.trim(),notes=$('#fieldNotes').value.trim();if(!label&&!notes)return;state.field_logs.unshift({id:'field-'+Date.now(),time:new Date().toISOString(),label,value:$('#fieldValue').value.trim(),unit:$('#fieldUnit').value.trim(),notes});state.field_logs=state.field_logs.slice(0,2000);['fieldLabel','fieldValue','fieldUnit','fieldNotes'].forEach(id=>$('#'+id).value='');saveState();renderFieldLogs()}
function renderFieldLogs(){const root=$('#fieldLogTable');if(!root)return;const rows=state.field_logs||[];if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noFieldLogs'))}</div>`;renderFieldTrend();return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('time')}</th><th>${tx('observation')}</th><th>${tx('value')}</th><th>${tx('notes')}</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(formatTime(x.time))}</td><td><strong>${esc(x.label||'—')}</strong></td><td>${esc(x.value||'—')} ${esc(x.unit||'')}</td><td>${esc(x.notes||'')}</td><td><button class="btn danger small" onclick="removeFieldLog('${arg(x.id)}')">×</button></td></tr>`).join('')}</tbody></table></div>`;renderFieldTrend()}
function numericFieldValue(v){if(typeof v==='number')return Number.isFinite(v)?v:null;const n=Number(String(v??'').trim().replace(',','.'));return Number.isFinite(n)?n:null}
function renderFieldTrend(){const sel=$('#fieldTrendSelect'),root=$('#fieldTrendChart');if(!sel||!root)return;const rows=(state.field_logs||[]).filter(x=>x.label&&numericFieldValue(x.value)!==null),labels=[...new Set(rows.map(x=>x.label))].sort((a,b)=>a.localeCompare(b,lang==='el'?'el':'en'));const current=sel.value;sel.innerHTML=`<option value="">${esc(tx('chooseObservation'))}</option>`+labels.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');sel.value=labels.includes(current)?current:(labels[0]||'');const chosen=sel.value,series=rows.filter(x=>x.label===chosen).sort((a,b)=>String(a.time).localeCompare(String(b.time))).slice(-100);if(series.length<2){root.innerHTML=`<div class="empty">${esc(tx('needTwoSamples'))}</div>`;return}const vals=series.map(x=>numericFieldValue(x.value)),lo=Math.min(...vals),hi=Math.max(...vals),span=hi-lo||1,pts=vals.map((v,i)=>[24+(i/(vals.length-1))*652,176-((v-lo)/span)*144]),unit=series.at(-1).unit||'';root.innerHTML=`<div class="trend-stats"><span><small>${esc(tx('latest'))}</small><strong>${fmt(vals.at(-1),2)} ${esc(unit)}</strong></span><span><small>${esc(tx('minimum'))}</small><strong>${fmt(lo,2)} ${esc(unit)}</strong></span><span><small>${esc(tx('maximum'))}</small><strong>${fmt(hi,2)} ${esc(unit)}</strong></span><span><small>${esc(tx('samples'))}</small><strong>${fmt(vals.length)}</strong></span></div><svg class="trend-chart" viewBox="0 0 700 200" role="img" aria-label="${esc(chosen)}"><line x1="24" y1="176" x2="676" y2="176" class="trend-axis"/><line x1="24" y1="32" x2="24" y2="176" class="trend-axis"/><polyline points="${pts.map(p=>p.map(x=>x.toFixed(1)).join(',')).join(' ')}" class="trend-line"/>${pts.map((p,i)=>`<circle cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="3" class="trend-point"><title>${esc(formatTime(series[i].time))}: ${esc(String(series[i].value))} ${esc(series[i].unit||'')}</title></circle>`).join('')}</svg>`}
function removeFieldLog(id){id=decodeURIComponent(id);state.field_logs=(state.field_logs||[]).filter(x=>x.id!==id);saveState();renderFieldLogs()}
function exportFieldLogCSV(){const rows=[['time','observation','value','unit','notes'],...(state.field_logs||[]).map(x=>[x.time,x.label,x.value,x.unit,x.notes])];downloadBlob(csvRows(rows),'offline-survival-field-log.csv','text/csv;charset=utf-8')}

function addVehicle(){const name=$('#vehName').value.trim();if(!name)return;state.vehicles.push({id:'vehicle-'+Date.now(),name,fuel_l:+$('#vehFuel').value||0,consumption_l100km:+$('#vehConsumption').value||0,battery_pct:+$('#vehBattery').value||0,odometer_km:+$('#vehOdo').value||0,last_check:$('#vehCheck').value,notes:''});['vehName','vehFuel','vehConsumption','vehBattery','vehOdo','vehCheck'].forEach(id=>$('#'+id).value='');saveState();renderVehicles()}
function vehicleRange(v){const c=+v.consumption_l100km||0;return c>0?(+v.fuel_l||0)/c*100:null}
function renderVehicles(){const root=$('#vehiclesTable'),sel=$('#tripVehicle');if(!root)return;const rows=state.vehicles||[];if(sel){const cur=sel.value;sel.innerHTML=`<option value="">${esc(tx('selectVehicle'))}</option>`+rows.map(v=>`<option value="${esc(v.id)}">${esc(v.name)}</option>`).join('');if(rows.some(v=>v.id===cur))sel.value=cur}if(!rows.length){root.innerHTML=`<div class="empty">${esc(tx('noVehicles'))}</div>`;return}root.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tx('vehicle')}</th><th>${tx('fuelLiters')}</th><th>${tx('consumption')}</th><th>${tx('estimatedRange')}</th><th>${tx('batteryPct')}</th><th>${tx('lastCheck')}</th><th></th></tr></thead><tbody>${rows.map(v=>`<tr><td><strong>${esc(v.name)}</strong></td><td>${fmt(v.fuel_l,1)} L</td><td>${fmt(v.consumption_l100km,1)}</td><td>${vehicleRange(v)==null?'—':fmt(vehicleRange(v),0)+' km'}</td><td>${fmt(v.battery_pct,0)}%</td><td>${esc(v.last_check||'—')}</td><td><button class="btn danger small" onclick="removeVehicle('${arg(v.id)}')">×</button></td></tr>`).join('')}</tbody></table></div>`}
function removeVehicle(id){id=decodeURIComponent(id);state.vehicles=(state.vehicles||[]).filter(x=>x.id!==id);saveState();renderVehicles()}
function calcTripRange(){const v=(state.vehicles||[]).find(x=>x.id===$('#tripVehicle').value);if(!v){$('#tripResult').textContent='—';return}const raw=vehicleRange(v);if(raw==null){$('#tripResult').textContent='—';return}const reserve=Math.max(0,Math.min(95,+$('#tripReserve').value||0))/100,usable=raw*(1-reserve),trip=Math.max(0,+$('#tripDistance').value||0),margin=usable-trip;$('#tripResult').innerHTML=`<strong>${tx('usableRange')}: ${fmt(usable,0)} km</strong><small>${tx('rangeMargin')}: ${fmt(margin,0)} km</small>`}

async function hashLibrary(path){$('#viewerTitle').textContent=tx('hashFile');$('#viewerBody').innerHTML=`<p>${esc(tx('hashing'))}</p><p><code>${esc(path)}</code></p>`;openModal('viewerModal');try{const d=await api(`/api/library/hash?path=${encodeURIComponent(path)}`);$('#viewerBody').innerHTML=`<p><strong>SHA-256</strong></p><div class="viewer mono">${esc(d.sha256)}</div><p class="muted">${esc(path)} · ${fmt(d.size)} bytes</p>`}catch(e){toast(e.message)}}
async function runDiagnostics(){const root=$('#diagnosticsPanel');if(!root)return;root.innerHTML=`<div class="empty">${esc(tx('loading'))}</div>`;try{const d=await api('/api/diagnostics');root.innerHTML=`<div class="results">${d.checks.map(x=>`<div class="result"><div class="toolbar"><strong>${esc(x.name)}</strong><span class="${x.ok?'audit-pass':'audit-fail'}">${esc(x.ok?tx('diagnosticPass'):tx('diagnosticFail'))}</span></div><small class="muted">${esc(x.detail||'')}</small></div>`).join('')}</div>`}catch(e){root.innerHTML=`<div class="empty audit-fail">${esc(e.message)}</div>`}}
async function restorePreviousState(){try{const q=await api('/api/state/previous');if(!q.available){toast(tx('noPreviousState'));return}state=mergeState(await api('/api/state/restore-previous',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}));hydrateForms();applyLang();toast(tx('previousRestored'))}catch(e){toast(e.message)}}
async function registerOfflineShell(){if(!('serviceWorker' in navigator))return false;try{await navigator.serviceWorker.register('/sw.js',{scope:'/'});return true}catch{return false}}

async function init(){applyLang();renderScenarios();$('#searchBtn').onclick=search;$('#searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')search()});$('#customInput').addEventListener('keydown',e=>{if(e.key==='Enter')addCustom()});$('#libraryContentQuery').addEventListener('keydown',e=>{if(e.key==='Enter')searchLibraryContents()});$('#langBtn').onclick=async()=>{lang=lang==='en'?'el':'en';localStorage.setItem('osp-lang',lang);$$('[data-loaded]').forEach(e=>delete e.dataset.loaded);applyLang();if(currentSection==='browse')loadCategories();if(currentSection==='essentials')loadEssentials(true);if(currentSection==='food')loadFood();if(currentSection==='library')refreshLibrary()};$('#integrityBtn').onclick=()=>go('system');try{meta=await api('/api/meta');state=mergeState(meta.state);applyLang();await registerOfflineShell()}catch(e){toast(e.message)}}
init();
